import{_ as o,c as e,o as t,ag as n}from"./chunks/framework.DJBJE7_Z.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"overview/faq.md","filePath":"overview/faq.md"}'),i={name:"overview/faq.md"};function s(a,r,g,l,c,p){return t(),e("div",null,r[0]||(r[0]=[n('<h3 id="_1-scribbleforge-是什么" tabindex="-1">1. ScribbleForge 是什么？ <a class="header-anchor" href="#_1-scribbleforge-是什么" aria-label="Permalink to &quot;1. ScribbleForge 是什么？&quot;">​</a></h3><p>ScribbleForge 是一款<strong>企业级跨端实时协作白板 SDK</strong>，它集成了基础的白板协作工具、文档同步展示和自定义插件管理系统。其核心目标是提供一个全面、高性能且灵活的互动白板解决方案，满足企业在远程协作、在线教育、创意设计等多种场景下的需求。</p><h3 id="_2-scribbleforge-和声网现有-white-sdk-是否兼容" tabindex="-1">2. ScribbleForge 和声网现有 White SDK 是否兼容？ <a class="header-anchor" href="#_2-scribbleforge-和声网现有-white-sdk-是否兼容" aria-label="Permalink to &quot;2. ScribbleForge 和声网现有 White SDK 是否兼容？&quot;">​</a></h3><p>ScribbleForge SDK 是基于 White SDK 的全量重构版本，<strong>互不兼容</strong>。相比 White SDK 在 API 和产品行为上有较大变更，在继承 White SDK 功能的基础上优化了 SDK 的内部架构，提供了几个关键的设计优势，使其成为一个强大且灵活的协作平台：</p><ul><li><p><strong>高度模块化</strong>：ScribbleForge 的设计基于<strong>Room</strong>、<strong>Application</strong> 和 <strong>ApplicationManager</strong> 等核心概念，实现了功能的<strong>模块化</strong>。这意味着您可以轻松地扩展功能，创建自定义的 <strong>Application</strong> 来满足特定需求，例如开发自己的白板或多媒体应用。</p></li><li><p><strong>强大的协作中心</strong>：<strong>Room</strong> 作为协作的中心枢纽，负责所有参与者的<strong>状态同步</strong>和核心模块的管理。这确保了所有用户都能拥有一致的协作体验。</p></li><li><p><strong>灵活的应用管理</strong>：<strong>ApplicationManager</strong> 提供了对 <strong>Application</strong> 生命周期（启动、关闭、注册）的集中控制。结合 <strong>WindowManager</strong>，您可以轻松管理多个 <strong>Application</strong> 窗口，实现多窗口布局和统一的交互空间。</p></li><li><p><strong>实时数据一致性</strong>：ScribbleForge 底层采用了 <strong>CRDTs (无冲突复制数据类型)</strong>，这保证了在多人协作时数据的<strong>一致性</strong>。所有用户的操作都会被高效同步，避免了冲突。</p></li><li><p><strong>用户友好的交互</strong>：<strong>UserManager</strong> 负责处理用户相关的逻辑，包括维护用户列表和分发事件，为用户管理提供了便利。<strong>WindowManager</strong> 提供的窗口化功能进一步增强了用户界面的灵活性和可操作性。</p></li></ul><p>声网 White SDK 将继续维护，长期来看推荐客户选择合适的时机升级到 ScribbleForge，以获得更好的产品体验，参考<a href="./migration-guide.html">《迁移指南》</a>.</p><h3 id="_3-scribbleforge-是否支持私有化部署" tabindex="-1">3. ScribbleForge 是否支持私有化部署？ <a class="header-anchor" href="#_3-scribbleforge-是否支持私有化部署" aria-label="Permalink to &quot;3. ScribbleForge 是否支持私有化部署？&quot;">​</a></h3><p>支持。</p><hr><p>如果您在使用 ScribbleForge 的过程中遇到其他问题，欢迎查阅更详细的官方文档或联系我们的技术支持团队。</p>',10)]))}const _=o(i,[["render",s]]);export{h as __pageData,_ as default};
